def transform(grid):
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    # Find all positions of 2
    positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2]

    # Build result initialized to 0
    result = [[0] * cols for _ in range(rows)]

    # Copy all 2s to result first
    for r, c in positions:
        result[r][c] = 2

    # Find rows with multiple 2s and fill between them
    for r in range(rows):
        cols_in_row = [c for c in range(cols) if grid[r][c] == 2]
        if len(cols_in_row) >= 2:
            min_c, max_c = min(cols_in_row), max(cols_in_row)
            for c in range(min_c, max_c + 1):
                if grid[r][c] == 2:
                    result[r][c] = 2
                else:
                    result[r][c] = 3

    # Find columns with multiple 2s and fill between them
    for c in range(cols):
        rows_in_col = [r for r in range(rows) if grid[r][c] == 2]
        if len(rows_in_col) >= 2:
            min_r, max_r = min(rows_in_col), max(rows_in_col)
            for r in range(min_r, max_r + 1):
                if grid[r][c] == 2:
                    result[r][c] = 2
                else:
                    result[r][c] = 3

    return result

